import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { withReboxFields } from "./codegen-metadata.mjs";
import * as Aff from "../output/Effect.Aff/index.js";
import * as Either from "../output/Data.Either/index.js";
import * as Ref from "../output/Effect.Ref/index.js";
import * as Map from "../output/Data.Map/index.js";
import * as Set from "../output/Data.Set/index.js";
import * as F from "../output/Data.Foldable/index.js";
import * as U from "../output/Data.Unfoldable/index.js";
import { ordString } from "../output/Data.Ord/index.js";
import { Just, Nothing } from "../output/Data.Maybe/index.js";
import { Tuple } from "../output/Data.Tuple/index.js";
import * as C from "../output/PureScript.Backend.Optimizer.CoreFn/index.js";
import { NeutralExpr } from "../output/PureScript.Backend.Optimizer.Semantics/index.js";
import * as S from "../output/PureScript.Backend.Optimizer.Syntax/index.js";
import * as Cache from "../output/Gopurs.Cache.Modules/index.js";

const run = aff => new Promise((resolve, reject) => Aff.runAff(result => () => result instanceof Either.Left ? reject(result.value0) : resolve(result.value0))(aff)());
const table = entries => Map.fromFoldable(ordString)(F.foldableArray)(entries.map(([name, value]) => new Tuple(name, value)));
const names = map => Set.toUnfoldable(U.unfoldableArray)(Map.keys(map));
const expr = syntax => new NeutralExpr(syntax);
const backend = owners => ({ name: "Reader", bindings: [{ recursive: false, bindings: owners.map(owner => new Tuple(owner, expr(new S.Var(new C.Qualified(new Just(owner), "f"))))) }] });

test("worker warming decodes only visible cached owners and commits complete batches", async t => {
  const directory = mkdtempSync(join(tmpdir(), "gopurs-worker-warm-"));
  const previous = process.env.GOPURS_COMPILER_SNAPSHOT;
  process.env.GOPURS_COMPILER_SNAPSHOT = directory;
  t.after(() => { if (previous === undefined) delete process.env.GOPURS_COMPILER_SNAPSHOT; else process.env.GOPURS_COMPILER_SNAPSHOT = previous; rmSync(directory, { recursive: true, force: true }); });
  const metadata = withReboxFields({ elidedCtors: Set.empty, ctorTypes: Map.empty, pointerAdtPaths: Map.empty, pointerAdtNodes: Set.empty, pointerAdtLeaves: Map.empty,
    enumAdts: Set.empty, enumCtors: Set.empty, globalTypes: Map.empty, globalFunctions: Map.empty, classDeclsFields: Map.empty });
  const payloads = {}, expected = {};
  const keys = { prepared: "prepared", optimizerEnvironment: "optimizer", callerDemands: "callers" };
  // Use the real emitter and worker codec, including non-empty signatures.
  for (const owner of ["Alpha", "Beta", "Late"]) {
    const stage = join(directory, "produce-" + owner), output = join(stage, "output");
    for (const child of ["modules", "output/purescript"]) mkdirSync(join(stage, child), { recursive: true });
    const cache = { session: { stage, output, context: "context" }, candidates: Map.empty, keys: Map.singleton(owner)(keys), metadata: "metadata", metadataDemands: Nothing.value,
      lazyContributions: false, reads: Ref.new(Map.empty)(), invalidations: Ref.new(Map.empty)(), restored: Ref.new(0)(), backends: Ref.new(Map.empty)(), ffiDigests: Map.empty, priorFfiDigests: Map.empty };
    const mod = { name: owner, path: owner + ".purs", comments: [], imports: Set.empty, exports: Set.empty, reExports: Set.empty, dataTypes: Map.empty, dataDecls: [], classDecls: [], foreign: Map.empty,
      implementations: Map.empty, directives: Map.empty,
      bindings: [{ recursive: false, bindings: [new Tuple("f", expr(new S.Typed(new C.Func([C.Int.value], C.Int.value), expr(new S.Abs([new Tuple(new Just("x"), 0)], expr(new S.Typed(C.Int.value, expr(new S.Local(new Just("x"), 0)))))))))] }] };
    expected[owner] = (await run(Cache.emit(cache)(Map.empty)(metadata)("workers")(false)({ path: owner + ".purs" })(mod))).functions;
    assert.ok(Map.size(expected[owner]) > 0);
    payloads[owner] = readFileSync(join(stage, "modules", owner, "3.json"), "utf8");
  }
  mkdirSync(join(directory, "tools"));
  writeFileSync(join(directory, "tools/build-cache-helper"), `#!/usr/bin/env node
const fs = require("node:fs"), path = require("node:path"), assert = require("node:assert/strict");
const request = JSON.parse(fs.readFileSync(0, "utf8")), mode = path.basename(request.stage);
fs.appendFileSync(path.join(request.stage, "requests.jsonl"), JSON.stringify({operation:request.operation,owners:request.owners}) + "\\n");
assert.deepEqual(request.parts, ["3"]);
if (request.operation === "materialize") {
  assert.deepEqual(request.owners, ["Late"]);
  console.log(JSON.stringify({status:"ready",reason:"",stage:request.stage,root:request.stage,cacheRoot:request.stage+"/.gopurs-cache",input:request.stage,inputLayout:"",output:request.stage,count:3,ffi:[],context:"same",sameTast:false,packageRequest:""}));process.exit(0);
}
assert.equal(request.operation, "read-parts");
const contributions=request.owners.map(name=>({name,part:"3",text:fs.readFileSync(path.join(request.stage,"prior",name,"3.json"),"utf8")}));
if(mode==="missing")contributions.pop();
if(mode==="duplicate")contributions[1]=contributions[0];
if(mode==="outside")contributions[0].name="Future";
if(mode==="wrong-part")contributions[0].part="2";
if(mode==="invalid")contributions[1].text="{}";
if(mode==="wrong-owner")contributions[1].text=contributions[0].text;
console.log(JSON.stringify(mode==="integrity-error"?{status:"error",reason:"corrupt pinned worker"}:{status:"ready",reason:"",contributions}));
`, { mode: 0o755 });
  function fixture(mode) {
    const stage = join(directory, mode); mkdirSync(stage);
    for (const owner of ["Alpha", "Beta", "Late"]) { mkdirSync(join(stage, "prior", owner), { recursive: true }); writeFileSync(join(stage, "prior", owner, "3.json"), payloads[owner]); }
    const parts = [{}, {}, {}, { codec: mode === "old-codec" ? "gopurs/workers-v1" : "gopurs/workers-v3" }];
    return { session: { stage }, lazyContributions: true, priorWorkers: Ref.new(Map.empty)(), priorHeaderDirectives: Map.empty, priorPartTexts: Map.empty, candidates: table(["Alpha", "Beta", "Late"].map(owner => [owner, { parts }])) };
  }
  const requests = cache => existsSync(join(cache.session.stage, "requests.jsonl")) ? readFileSync(join(cache.session.stage, "requests.jsonl"), "utf8").trim().split("\n").map(JSON.parse) : [];
  const snapshot = table([["Alpha", Nothing.value], ["Beta", Nothing.value], ["Current", new Just(Map.empty)], ["Unused", Nothing.value]]);
  const reader = backend(["Alpha", "Beta", "Alpha", "Current", "Reader", "Future"]);
  for (const jobs of [1, 8]) {
    const cache = fixture("valid-" + jobs);
    await run(Cache.warmWorkerSnapshot(jobs)(cache)(snapshot)([reader, reader]));
    assert.deepEqual(names(Ref.read(cache.priorWorkers)()), ["Alpha", "Beta"]);
    assert.deepEqual(requests(cache), [{ operation: "read-parts", owners: ["Alpha", "Beta"] }]);
    for (const owner of ["Alpha", "Beta"]) rmSync(join(cache.session.stage, "prior", owner, "3.json"));
    await run(Cache.warmWorkerSnapshot(jobs)(cache)(snapshot)([reader]));
    const resolve = Cache.resolveWorkerSnapshot(Cache.readWorkerContribution(cache))(snapshot);
    assert.deepEqual(names(await run(resolve(reader))), ["Alpha.f", "Beta.f"]);
    assert.equal(requests(cache).length, 1, "shared owners decode once, with no future/current/unused load");
    assert.deepEqual(await run(Cache.readWorkerContribution(cache)("Late")), expected.Late, "unpredicted owners retain the individual loader");
    assert.deepEqual(requests(cache)[1], { operation: "materialize", owners: ["Late"] });
    const fresh = table([["Alpha", new Just(Map.empty)]]);
    assert.deepEqual(names(await run(Cache.resolveWorkerSnapshot(Cache.readWorkerContribution(cache))(fresh)(backend(["Alpha"])))), [], "fresh signatures override private cached values");
  }
  for (const mode of ["missing", "duplicate", "outside", "wrong-part", "invalid", "wrong-owner", "integrity-error", "old-codec"]) {
    const cache = fixture(mode);
    await assert.rejects(run(Cache.warmWorkerSnapshot(8)(cache)(snapshot)([reader])), /incremental cache:/, mode);
    assert.deepEqual(names(Ref.read(cache.priorWorkers)()), [], mode + ": no partial memo publication");
  }
  for (const mode of ["empty-batch", "eager"]) {
    const cache = fixture(mode); if (mode === "eager") cache.lazyContributions = false;
    await run(Cache.warmWorkerSnapshot(8)(cache)(snapshot)(mode === "empty-batch" ? [] : [reader]));
    assert.deepEqual(requests(cache), []);
  }
});

src/Gopurs/CodegenState.purs.text:
module Gopurs.CodegenState
  ( CodegenMetadataRow
  , CodegenMetadata
  , CodegenMetadataWith
  , SharedMetadataRow
  , CodegenState
  , FunctionInfo
  , ArrayFoldDescriptor
  , CodePointFoldDescriptor
  ) where

import Data.Map (Map)
import Data.Maybe (Maybe)
import Data.Set (Set)
import Data.Set as Set
import Data.Tuple (Tuple)
import Gopurs.Cache.LookupTable (LookupTable)
import Gopurs.AdtMetadata (PointerAdtLeaf, PointerAdtPaths)
import Gopurs.ClassMetadata (ClassFields)
import Gopurs.ConstructorMetadata (ConstructorTypes)
import Gopurs.GoAst (GoDecl, GoType)
import Gopurs.GoSymbol (GoReference)
import Gopurs.ReboxMetadata (ReboxFieldIndex)
import PureScript.Backend.Optimizer.CoreFn (ExprType)
import PureScript.Backend.Optimizer.Semantics (NeutralExpr)

-- A closed scalar indexed fold can consume a producer without materializing it.
-- The callback is serialized with the worker signature, so changes invalidate callers.
type ArrayFoldDescriptor = { callback :: NeutralExpr, seed :: Int }

type CodePointFoldDescriptor = { callback :: NeutralExpr, seed :: Int }

type FunctionInfo =
  { reference :: GoReference
  , fArgs :: Array GoType
  , fRet :: GoType
  , arity :: Int
  , arrayFold :: Maybe ArrayFoldDescriptor
  , codePointFold :: Maybe CodePointFoldDescriptor
  }

-- Prepared metadata is shared by the generator and value conversions.
-- It is passed directly to each translation, never stored in a mutable Ref.
-- Driver.Prepare builds declaration/type tables from the original TAST, with
-- synthetic class data declarations used only for pointer layouts. Driver.Build
-- supplies the published native signatures for the current emission batch;
-- Driver.Output adds the current module's FFI signatures before translation.
type SharedMetadataRow :: Row Type
type SharedMetadataRow =
  ( sharedRecords :: Set String
  , elidedCtors :: Set.Set String
  , ctorTypes :: ConstructorTypes
  , pointerAdtPaths :: PointerAdtPaths
  , pointerAdtNodes :: Set String
  , pointerAdtLeaves :: Map String PointerAdtLeaf
  , enumAdts :: Set.Set String
  , enumCtors :: Set.Set String
  , globalFunctions :: Map String FunctionInfo
  -- | Native call metadata for the current module's FFI (key: raw identifier).
  , ffiFunctions :: Map String FunctionInfo
  , classDeclsFields :: ClassFields
  , reboxFields :: ReboxFieldIndex
  )

type CodegenMetadataWith globals = { globalTypes :: globals | SharedMetadataRow }

type CodegenMetadataRow = ( globalTypes :: LookupTable ExprType | SharedMetadataRow )

type CodegenMetadata = { | CodegenMetadataRow }

-- Only output accumulated during one translation belongs in the mutable state.
type CodegenState =
  { declarations :: Array GoDecl
  , globalId :: Int
  , reboxPairs :: Set.Set (Tuple GoType GoType)
  }

tools/affine-loops.test.mjs.text:
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import test from 'node:test';

const output = process.argv[2] ?? fileURLToPath(new URL('../output/', import.meta.url));
const load = name => import(pathToFileURL(resolve(output, name, 'index.js')));
const [Go, A, C, S, T, Maybe, M, Ord, Tuples, Free, Printer, Context] = await Promise.all([
    'Gopurs.GoAst', 'Gopurs.AffineLoops', 'PureScript.Backend.Optimizer.CoreFn',
    'PureScript.Backend.Optimizer.Syntax', 'PureScript.Backend.Optimizer.Codegen.Tco',
    'Data.Maybe', 'Data.Map', 'Data.Ord', 'Data.Tuple',
    'PureScript.Backend.Optimizer.FreeVars', 'Gopurs.Printer', 'Gopurs.ExprContext',
].map(load));
const { Just, Nothing } = Maybe, { Tuple } = Tuples;
const int = C.Int.value, i64 = Go.TypeInt64.value;
const expr = syntax => new T.TcoExpr(null, syntax);
const typed = (type, value) => expr(new S.Typed(type, value));
const local = (name, level) => typed(int, expr(new S.Local(new Just(name), level)));
const counter = local('remaining', 0), accumulator = local('seed', 1);
const counterName = Free.localId(new Just('remaining'))(0), accumulatorName = Free.localId(new Just('seed'))(1);
const params = [new Tuple(counterName, i64), new Tuple(accumulatorName, i64)];
const integer = n => typed(int, expr(new S.Lit(new C.LitInt(n))));
const variable = (name = 'repeat', owner = 'Probe') => expr(new S.Var(new C.Qualified(new Just(owner), name)));
const binary = (operator, left, right, type = int) => typed(type, expr(new S.PrimOp(new S.Op2(operator, left, right))));
const add = (left, right) => binary(new S.OpIntNum(S.OpAdd.value), left, right);
const subtract = (left, right) => binary(new S.OpIntNum(S.OpSubtract.value), left, right);
const modulo = (left, right) => binary(new S.OpIntNum(S.OpMod.value), left, right);
const condition = binary(new S.OpIntOrd(S.OpEq.value), counter, integer(0), C.Boolean.value);
const call = (target, args) => typed(int, expr(new S.App(target, args)));
const sentinel = new Go.GoReturn(new Go.GoInt(-98));
const self = A.globalTarget('Probe')('repeat');
function fixture(options = {}) {
    const conditionExpr = options.condition ?? condition;
    const decrement = options.decrement ?? subtract(counter, integer(1));
    const update = options.update ?? add(accumulator, integer(options.increment ?? 1));
    const step = options.step ?? call(options.target ?? variable(), [decrement, update]);
    return typed(int, expr(new S.Branch([new S.Pair(conditionExpr, options.seed ?? accumulator)], step)));
}
const readContext = { depth: 0, mbExpectedExprType: new Just(int), mbExpectedGoType: new Just(i64),
    options: { isTail: true, inEffectBlock: true }, tcoIdent: new Just('repeat'), loopCtx: [], recVars: [] };
const noReads = () => () => () => { throw new Error('unexpected global read'); };
function optimize(body, parameters = params, result = i64, target = self, fallback = sentinel, translate = noReads) {
    const before = JSON.stringify(body);
    const value = A.wrap(translate)(readContext)(target)(parameters)(result)(body)(fallback);
    assert.equal(JSON.stringify(body), before, 'input IR remains immutable');
    return value;
}

test('affine admission proves the entire recurrence and the exact self target', () => {
    for (const increment of [-2147483648, -7, 0, 1, 7, 2147483647]) {
        const body = fixture({ increment });
        const result = optimize(body);
        assert.notEqual(result, sentinel);
        const code = Printer.printGoExpr(result);
        assert.match(code, /int64\(int32\(/);
        assert.match(code, /\*.*int64\(/);
        assert.doesNotMatch(code, /IntMul/);
        assert.match(code, /2147483647/);
        assert.equal(result.value0.at(-1), sentinel, 'fallback is unchanged');
    }
    const swapped = fixture({ condition: binary(new S.OpIntOrd(S.OpEq.value), integer(0), counter, C.Boolean.value),
        update: add(integer(-3), accumulator) });
    assert.notEqual(optimize(swapped), sentinel);
    const localSelf = local('nested', 7), localKey = Free.localId(new Just('nested'))(7);
    const bound = M.insert(Ord.ordString)(localKey)({ name: 'allocated_worker', goType: i64 })(M.empty);
    assert.notEqual(optimize(fixture({ target: localSelf }), params, i64, A.localTarget(bound)('allocated_worker')), sentinel);
    assert.equal(optimize(fixture({ target: localSelf }), params, i64, A.localTarget(bound)('another_worker')), sentinel);
});

test('affine admission rejects calls, effects, changing increments and altered recurrences', () => {
    const options = [
        { target: variable('different') }, { target: variable('repeat', 'Foreign') },
        { decrement: subtract(counter, integer(2)) }, { decrement: add(counter, integer(1)) },
        { update: add(accumulator, counter) }, { update: subtract(accumulator, integer(1)) },
        { update: call(variable('observe'), [accumulator]) },
        { update: add(accumulator, integer(4294967295)) },
        { seed: counter }, { seed: add(accumulator, integer(1)) },
        { condition: binary(new S.OpIntOrd(S.OpLt.value), counter, integer(0), C.Boolean.value) },
        { step: call(variable(), [subtract(counter, integer(1)), accumulator, integer(1)]) },
        { step: expr(new S.EffectPure(integer(1))) },
    ];
    for (const option of options) assert.equal(optimize(fixture(option)), sentinel);
    const effectBefore = expr(new S.Let(Nothing.value, 9, call(variable('observe'), [accumulator]), fixture()));
    assert.equal(optimize(effectBefore), sentinel);
    assert.equal(optimize(fixture(), [...params, new Tuple('extra', i64)]), sentinel);
    assert.equal(optimize(fixture(), [new Tuple(counterName, Go.TypeFloat64.value), params[1]]), sentinel);
    assert.equal(optimize(fixture(), params, Go.TypeValue.value), sentinel);
});

test('remainder periods require the same counter and a positive canonical literal divisor', () => {
    for (const divisor of [1, 2, 3, 7, 65537, 2147483647]) {
        const result = optimize(fixture({update:add(accumulator,modulo(counter,integer(divisor)))}));
        assert.notEqual(result,sentinel);
        assert.equal(result.value0.at(-1),sentinel);
        assert.doesNotMatch(Printer.printGoExpr(result),/IntMul/);
        assert.notEqual(optimize(fixture({update:add(modulo(counter,integer(divisor)),accumulator)})),sentinel);
    }
    for (const value of [modulo(counter,integer(0)),modulo(counter,integer(-3)),
        modulo(counter,integer(2147483648)),modulo(accumulator,integer(3)),
        modulo(subtract(counter,integer(1)),integer(3)),modulo(counter,accumulator),
        modulo(counter,call(variable('divisor'),[integer(3)]))]) {
        assert.equal(optimize(fixture({update:add(accumulator,value)})),sentinel);
    }
    const stepped=letRead('first',2,call(variable(),[subtract(counter,integer(1)),
        add(accumulator,letRead('second',3,modulo(counter,integer(7))))]));
    const code=Printer.printGoExpr(optimize(fixture({step:stepped}),params,i64,self,sentinel,translateRead));
    assert.ok(code.indexOf('GetFirst()')<code.indexOf('GetSecond()'));
    assert.equal((code.match(/GetFirst\(\)/g)??[]).length,1);
    assert.equal((code.match(/GetSecond\(\)/g)??[]).length,1);
});

const selfStep = () => call(variable(), [subtract(counter, integer(1)), add(accumulator, integer(60))]);
const letRead = (name, level, body, value = variable(name, 'RenamedGlobals')) =>
    expr(new S.Let(new Just(name), level, value, body));
const twoReads = () => letRead('first', 2, letRead('second', 3, selfStep()));
const nestedReadStep = () => letRead('first', 2, call(variable(), [subtract(counter, integer(1)),
    add(accumulator, expr(new S.Let(Nothing.value, 3, variable('second', 'RenamedGlobals'), integer(60))))]));
const translateRead = context => nextId => value => {
    assert.equal(context.mbExpectedExprType, Nothing.value, 'the Int result expectation must not reach a global read');
    assert.equal(context.mbExpectedGoType, Nothing.value);
    assert.deepEqual(context.options, {isTail:false, inEffectBlock:false});
    while (value.value1 instanceof S.Typed) value = value.value1.value1;
    assert.ok(value.value1 instanceof S.Var);
    const name = value.value1.value0.value1;
    return {stmts: new Context.StmtLeaf(Go.rawGo(`trace += "${name === 'first' ? 'a' : 'b'}"`)),
        expr: new Go.GoCall(new Go.GoVar(name === 'first' ? 'GetFirst' : 'GetSecond'), []),
        exprType:i64, nextId:nextId + 1};
};

test('affine recurrence admits only unused strict global reads in the recursive branch', () => {
    const body = fixture({step:twoReads()});
    const result = optimize(body, params, i64, self, sentinel, translateRead);
    assert.notEqual(result, sentinel);
    assert.equal(result.value0.at(-1), sentinel);
    const code = Printer.printGoExpr(result);
    assert.ok(code.indexOf('>') < code.indexOf('GetFirst()'), 'positive guard precedes reads');
    assert.ok(code.indexOf('GetFirst()') < code.indexOf('GetSecond()'));
    assert.equal((code.match(/GetFirst\(\)/g) ?? []).length, 1);
    assert.equal((code.match(/GetSecond\(\)/g) ?? []).length, 1);

    const unsupported = [
        letRead('first', 2, selfStep(), call(variable('observe'), [integer(0)])),
        letRead('first', 2, selfStep(), local('captured', 9)),
        letRead('first', 2, selfStep(), expr(new S.Accessor(variable('object'), new S.GetProp('value')))),
        letRead('first', 2, selfStep(), expr(new S.EffectPure(integer(0)))),
        letRead('first', 2, call(variable(), [subtract(counter, integer(1)), add(accumulator, local('first', 2))])),
        // A rebinding of the exact counter level cannot masquerade as unused.
        letRead('remaining', 0, selfStep()),
    ];
    for (const step of unsupported) assert.equal(optimize(fixture({step})), sentinel);
    let tooMany = selfStep();
    for (let i=0; i<65; i++) tooMany = letRead('unused'+i, 20+i, tooMany);
    assert.equal(optimize(fixture({step:tooMany})), sentinel);
    assert.equal(optimize(letRead('first',2,fixture())),sentinel,'a read outside the branch cannot move under a positive guard');
});

test('affine constant operands retain strict demands after the step prefix', () => {
    const body = fixture({step:nestedReadStep()});
    const result = optimize(body, params, i64, self, sentinel, translateRead);
    assert.notEqual(result, sentinel);
    const code = Printer.printGoExpr(result);
    assert.ok(code.indexOf('GetFirst()') < code.indexOf('GetSecond()'));
    for (const update of [
        add(accumulator, letRead('first', 2, integer(60))),
        add(letRead('first', 2, integer(60)), accumulator),
    ]) assert.notEqual(optimize(fixture({update}),params,i64,self,sentinel,translateRead),sentinel);
    for (const value of [call(variable('observe'),[integer(0)]),local('captured',9),
        expr(new S.Accessor(variable('object'),new S.GetProp('value'))),expr(new S.EffectPure(integer(0)))]) {
        assert.equal(optimize(fixture({update:add(accumulator,letRead('unused',2,integer(60),value))})),sentinel);
    }
    assert.equal(optimize(fixture({update:add(accumulator,letRead('first',2,local('first',2)))})),sentinel);
    assert.equal(optimize(fixture({update:add(letRead('first',2,accumulator),integer(60))})),sentinel,
        'only the proven constant operand may contain reads');
    let constant = integer(60);
    for (let i=0;i<64;i++) constant=letRead('unused'+i,20+i,constant);
    assert.equal(optimize(fixture({step:letRead('first',2,call(variable(),[
        subtract(counter,integer(1)),add(accumulator,constant)]))})),sentinel,'the read budget spans both positions');
});

test('strict affine fast path keeps first initialization, order, failure and zero-demand behavior', t => {
    const directory = mkdtempSync(join(tmpdir(), 'gopurs-affine-reads-'));
