const root = fileURLToPath(new URL("../", import.meta.url));
const env = { ...process.env, GOWORK: "off" };
const run = (command, args, cwd, input, environment = env) => execFileSync(command, args, {
  cwd, input, encoding: "utf8", env: environment, timeout: 120_000,
  maxBuffer: 16 * 1024 * 1024, stdio: ["pipe", "pipe", "pipe"],
});

test("cache integrity, invalidation, publication and process death under the Go race detector", () => {
  const result = run("go", ["test", "-race", "-count=1", "-timeout=90s", "-v", "./..."], join(root, "tools/build-cache"));
  for (const name of ["ContentInvalidation", "IntegrityAndVersionMisses", "WorkspaceIsolation",
    "OwnershipTidyAndWriteElision", "WireArtifacts", "ConcurrentPublishers", "InterruptedPublicationAndKernelLock"]) {
    assert.ok(result.includes(`--- PASS: Test${name} `), result);
  }
});

test("JS and directly linked Go bridges exchange a content-verified persistent manifest", t => {
  const workspace = mkdtempSync(join(tmpdir(), "gopurs-build-cache-hosts-"));
  const previousPackSetting = process.env.GOPURS_PACK_PUBLICATION;
  process.env.GOPURS_PACK_PUBLICATION = "1";
  t.after(() => {
    rmSync(workspace, { recursive: true, force: true });
    if (previousPackSetting === undefined) delete process.env.GOPURS_PACK_PUBLICATION;
    else process.env.GOPURS_PACK_PUBLICATION = previousPackSetting;
  });
  const put = (path, content) => {
    mkdirSync(dirname(join(workspace, path)), { recursive: true });
    writeFileSync(join(workspace, path), content);
  };
  // Compile the actual FFI and the exact same copied package used by bootstrap.
  put("native/go.mod", "module gopurs/output\n\ngo 1.22\n");
  run(process.execPath, [join(root, "tools/build/prepare-native-output.mjs"), join(workspace, "native")], root);
  put("native/gopurs_runtime/runtime.go", readFileSync(join(root, "runtime/runtime.go"), "utf8"));
  put("native/bridge/bridge.go", readFileSync(join(root, "src/Gopurs/BuildCache.go"), "utf8")
    .replace("package Gopurs_BuildCache", "package bridge"));
  put("native/main.go", `package main
import ("fmt"; "io"; "os"; "gopurs/output/bridge")
func main() { b, err := io.ReadAll(os.Stdin); if err != nil { panic(err) }; fmt.Print(bridge.Exchange(string(b), nil)) }
`);
  const native = join(workspace, "linked-cache");
  run("go", ["build", "-o", native, "."], join(workspace, "native"));
  const packedEnv = { ...env, GOPURS_PACK_PUBLICATION: "1" };
  const nativeExchange = request => run(native, [], workspace, request, packedEnv);
  put("compiler", "identical artifact for this protocol comparison");
  put("output/Main/corefn.json", '{"moduleName":["Main"],"typeTable":[]}');
  put("stage/Main.go", "package purescript\n// revision one\n");
  put("stage/unit.json", '["unit"]');
  put("stage/module.go", "package purescript\n// module source\n");
  const key = value => createHash("sha256").update(value).digest("hex");
  const request = {
    schema: 1, operation: "snapshot",
    spec: {
      workspace, output: "output",
      compiler: [{ name: "compiler", kind: "file", path: "compiler" }],
      options: [{ name: "main", value: "Main" }],
      inputs: [{ name: "tast", kind: "tast", path: "output" }],
    },
    outputs: [{ path: "purescript/Main.go", kind: "module", module: "Main", source: "stage/Main.go" }],
    modules: [{
      name: "Main", prepared: key("prepared"), optimizerEnvironment: key("optimizer"),
      emitterEnvironment: key("emitter"), callerDemands: key("callers"),
      parts: ["pbo/backend-v2", "pbo/implementations-v1", "pbo/directives-v1", "gopurs/workers-v4"]
        .map(codec => ({ codec, source: "stage/unit.json" })),
      sources: [{ kind: "module", source: "stage/module.go" }],
    }],
  };
  const exchange = req => jsExchange(JSON.stringify(req))();
  const js = exchange(request);
  assert.equal(js, nativeExchange(JSON.stringify(request)), "wire responses must be byte-identical");
  request.operation = "publish";
  request.expectedKey = JSON.parse(js).snapshot.key;
  const published = JSON.parse(exchange(request));
  assert.equal(published.status, "published");
  assert.ok(existsSync(join(workspace, "output/.gopurs-cache/packs/index.json")), "pack index missing");
  request.operation = "lookup";
  const found = JSON.parse(nativeExchange(JSON.stringify(request)));
  assert.equal(found.status, "hit");
  assert.deepEqual(found.manifest, published.manifest);
  assert.equal(exchange(request), nativeExchange(JSON.stringify(request)));
  const file = readFileSync(join(workspace, "output/purescript/Main.go"));
  assert.equal(createHash("sha256").update(file).digest("hex"), found.manifest.outputs[0].object.sha256);
  put("stage/Main.go", "package purescript\n// revision two\n");
  request.operation = "publish";
  assert.equal(JSON.parse(nativeExchange(JSON.stringify(request))).status, "published");
  request.operation = "lookup";
  assert.equal(JSON.parse(exchange(request)).status, "hit");
  assert.match(readFileSync(join(workspace, "output/purescript/Main.go"), "utf8"), /revision two/);
  assert.equal(resolveBuildCacheHelper(), resolveBuildCacheHelper(), "helper is reused by source content");
});

tools/build-cache/contract.go.text:
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const Schema = 1
const Format = "gopurs-build-cache"

// Keys use byte-length framing, not a host's JSON serialization or ADT layout.
// Every component is UTF-8; sorted sets are ordered by UTF-8 bytes.
func Key(domain string, parts ...string) string {
	h := sha256.New()
	for _, part := range append([]string{Format, strconv.Itoa(Schema), domain}, parts...) {
		fmt.Fprintf(h, "%d:", len(part))
		h.Write([]byte(part))
	}
	return hex.EncodeToString(h.Sum(nil))
}

type Setting struct {
	Name  string `json:"name"`
	Value string `json:"value"`
}

// file includes absence and symlink resolution. directory observes immediate
// entries (for the FFI resolver's search-root inventory). tast observes exactly
// the immediate <module>/corefn.json files, without decoding them.
type Input struct {
	Name string `json:"name"`
	Kind string `json:"kind"`
	Path string `json:"path"`
}

type Spec struct {
	Workspace string    `json:"workspace"`
	Output    string    `json:"output"`
	Compiler  []Input   `json:"compiler"`
	Options   []Setting `json:"options"`
	Inputs    []Input   `json:"inputs"`
}

type Fingerprint struct {
	Name     string `json:"name"`
	Kind     string `json:"kind"`
	Path     string `json:"path"`
	Resolved string `json:"resolved"`
	State    string `json:"state"`
	Digest   string `json:"digest"`
}

type Snapshot struct {
	Workspace string        `json:"workspace"`
	Output    string        `json:"output"`
	Compiler  string        `json:"compiler"`
	Key       string        `json:"key"`
	Inputs    []Fingerprint `json:"inputs"`
}

type Object struct {
	SHA256 string `json:"sha256"`
	Bytes  int64  `json:"bytes"`
}

type OwnedOutput struct {
	Path   string `json:"path"`
	Kind   string `json:"kind"`
	Module string `json:"module"`
	Object Object `json:"object"`
}

type StagedOutput struct {
	Path   string `json:"path"`
	Kind   string `json:"kind"`
	Module string `json:"module"`
	Source string `json:"source"`
}

type Artifact struct {
	Codec  string `json:"codec"`
	Object Object `json:"object"`
}

type StagedArtifact struct {
	Codec  string `json:"codec"`
	Source string `json:"source"`
}

// The package resolver consumes the unqualified module/FFI source again after
// an edit. Its compressed object is private, never a compiler-owned Go output.
type ModuleSource struct {
	Kind   string `json:"kind"`
	Codec  string `json:"codec"`
	Object Object `json:"object"`
	Raw    Object `json:"raw"`
}

type StagedModuleSource struct {
	Kind   string `json:"kind"`
	Source string `json:"source"`
}

// A module memo is all-or-nothing. These are independent semantic environments,
// not merely an import/signature hash. Their producer must include absent reads,
// inlined bodies, ABI/layouts and transitive caller specialization demands.
type ModuleMemo struct {
	Name                 string         `json:"name"`
	Prepared             string         `json:"prepared"`
	OptimizerEnvironment string         `json:"optimizerEnvironment"`
	EmitterEnvironment   string         `json:"emitterEnvironment"`
	CallerDemands        string         `json:"callerDemands"`
	Metadata             string         `json:"metadata,omitempty"`
	FFIDigest            string         `json:"ffiDigest,omitempty"`
	Parts                []Artifact     `json:"parts"`
	Reads                *Artifact      `json:"reads,omitempty"`
	Capsule              *Artifact      `json:"capsule,omitempty"`
	Sources              []ModuleSource `json:"sources,omitempty"`
}

type StagedModule struct {
	Inherited            bool                 `json:"inherited,omitempty"`
	Name                 string               `json:"name"`
	Prepared             string               `json:"prepared"`
	OptimizerEnvironment string               `json:"optimizerEnvironment"`
	EmitterEnvironment   string               `json:"emitterEnvironment"`
	CallerDemands        string               `json:"callerDemands"`
	Metadata             string               `json:"metadata,omitempty"`
	FFIDigest            string               `json:"ffiDigest,omitempty"`
	Parts                []StagedArtifact     `json:"parts"`
	Reads                *StagedArtifact      `json:"reads,omitempty"`
	Capsule              *StagedArtifact      `json:"capsule,omitempty"`
	Sources              []StagedModuleSource `json:"sources,omitempty"`
}

type Manifest struct {
	Format   string        `json:"format"`
	Schema   int           `json:"schema"`
	Snapshot Snapshot      `json:"snapshot"`
	Outputs  []OwnedOutput `json:"outputs"`
	// Module order is the producer's canonical dependency order, never map order.
	Modules     []ModuleMemo `json:"modules"`
	Diagnostics *Artifact    `json:"diagnostics"`
	GoMod       string       `json:"goMod"`
	GoSum       string       `json:"goSum"`
}

type Request struct {
	Schema          int             `json:"schema"`
	Operation       string          `json:"operation"`
	Spec            Spec            `json:"spec"`
	ExpectedKey     string          `json:"expectedKey"`
	Outputs         []StagedOutput  `json:"outputs"`
	Modules         []StagedModule  `json:"modules"`
	Diagnostics     *StagedArtifact `json:"diagnostics"`
	checkLegacy     bool
	inherited       *Manifest // private session snapshot; never accepted over JSON
	inheritedStore  *store
	expectedOutputs map[string]Object // internal package references; never accepted over JSON
}

type Response struct {
	Schema   int       `json:"schema"`
	Status   string    `json:"status"`
	Reason   string    `json:"reason,omitempty"`
	Snapshot *Snapshot `json:"snapshot,omitempty"`
	Manifest *Manifest `json:"manifest,omitempty"`
}

var digestPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)
var goPackagePattern = regexp.MustCompile(`^p_(root|[0-9a-f]{32})$`)
var hexUnitsPattern = regexp.MustCompile(`^([0-9a-f]{4})*$`)
var floatPattern = regexp.MustCompile(`^[0-9a-f]{16}$`)
var integerPattern = regexp.MustCompile(`^(0|-?[1-9][0-9]*)$`)
var tagPattern = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9_./-]*$`)

var moduleCodecs = []string{"pbo/backend-v2", "pbo/implementations-v1", "pbo/directives-v1", "gopurs/workers-v4"}

const moduleReadsCodec = "gopurs/reads-owners-v1"

func validModule(name string) bool {
	if name == "" || strings.ContainsAny(name, "/\\\x00") {
		return false
	}
	for _, part := range strings.Split(name, ".") {
		if part == "" {
			return false
		}
	}
	return true
}

func outputPath(kind, module, path string) bool {
	if filepath.IsAbs(path) || strings.ContainsAny(path, "\\\x00") || filepath.ToSlash(filepath.Clean(path)) != path {
		return false
	}
	goName := strings.ReplaceAll(module, ".", "_")
	switch kind {
	case "module":
		return validModule(module) && path == "purescript/"+goName+".go"
	case "ffi":
		return validModule(module) && path == "purescript/"+goName+"_ffi.go"
	case "runtime":
		return module == "" && path == "gopurs_runtime/runtime.go"
	case "entry":
		return validModule(module) && (path == "main/main.go" || path == module+"/main/main.go")
	case "package", "ffi-package", "order", "package-init":
		parts := strings.Split(path, "/")
		if len(parts) != 3 || parts[0] != "purescript" {
			return false
		}
		if kind == "package-init" {
			return module == "" && (parts[1] == "init_all" || parts[1] == "init_external") && parts[2] == "init.go"
		}
		if !goPackagePattern.MatchString(parts[1]) {
			return false
		}
		if kind == "order" {
			return module == "" && parts[2] == "zz_gopurs_order.go"
		}
		if kind == "package" && module == "" {
			return parts[2] == "0_gopurs_package.go"
		}
		suffix := ".go"
		if kind == "ffi-package" {
			suffix = "_ffi.go"
		}
		return validModule(module) && parts[2] == goName+suffix
	}
	return false
}

func validObject(obj Object) bool {
	return digestPattern.MatchString(obj.SHA256) && obj.Bytes >= 0 && obj.Bytes <= 9007199254740991
}

func validateManifest(m Manifest) error {
	if m.Format != Format || m.Schema != Schema {
		return fmt.Errorf("manifest-version")
	}
	if !digestPattern.MatchString(m.Snapshot.Key) || !digestPattern.MatchString(m.Snapshot.Compiler) {
		return fmt.Errorf("manifest-key")
	}
	if m.GoMod != "create-if-absent" || m.GoSum != "external" {
		return fmt.Errorf("module-ownership")
	}
	seen := map[string]bool{}
	previous := ""
	for _, out := range m.Outputs {
		if !outputPath(out.Kind, out.Module, out.Path) || !validObject(out.Object) || seen[out.Path] || out.Path < previous {
			return fmt.Errorf("output-inventory")
		}
		seen[out.Path] = true
		previous = out.Path
	}
	seen = map[string]bool{}
	for _, mod := range m.Modules {
		if !validModule(mod.Name) || seen[mod.Name] {
			return fmt.Errorf("module-inventory")
		}
		seen[mod.Name] = true
		for _, key := range []string{mod.Prepared, mod.OptimizerEnvironment, mod.EmitterEnvironment, mod.CallerDemands} {
			if !digestPattern.MatchString(key) {
				return fmt.Errorf("module-environment")
			}
		}
		if len(mod.Parts) != len(moduleCodecs) {
			return fmt.Errorf("module-parts")
		}
		for i, part := range mod.Parts {
			// Keep legacy manifests readable for ownership and recovery. The typed
			// producer only reuses a backend whose business codec it understands.
			legacyBody := i == 0 && part.Codec == "pbo/backend-v1"
			legacyWorkers := i == 3 && (part.Codec == "gopurs/workers-v1" || part.Codec == "gopurs/workers-v2" || part.Codec == "gopurs/workers-v3")
			if (part.Codec != moduleCodecs[i] && !legacyBody && !legacyWorkers) || !validObject(part.Object) {
				return fmt.Errorf("module-codec")
			}
		}
		if mod.Reads != nil && (mod.Reads.Codec != moduleReadsCodec || !validObject(mod.Reads.Object)) {
			return fmt.Errorf("module-reads-codec")
		}
		if len(mod.Sources) > 2 {
			return fmt.Errorf("module-source-inventory")
		}
		for i, source := range mod.Sources {
			if source.Kind != []string{"module", "ffi"}[i] || source.Codec != moduleSourceCodec || !validObject(source.Object) || !validObject(source.Raw) {
				return fmt.Errorf("module-source-codec")
			}
		}
	}
	if m.Diagnostics != nil && (m.Diagnostics.Codec != "gopurs/diagnostics-v1" || !validObject(m.Diagnostics.Object)) {
		return fmt.Errorf("diagnostic-codec")
	}
	return nil
}

// The driver records PBO read owners as newline-delimited module names.
// Empty input proves no reads; an absent artifact provides no such proof.
func validateReadOwners(data []byte) error {
	for _, owner := range strings.Split(string(data), "\n") {
		if owner != "" && (!validModule(owner) || strings.ContainsAny(owner, " \t\r")) {
			return fmt.Errorf("module-reads-owner")
		}
	}
	return nil
}

// Lossless wire values have explicit, stable tags. Strings are UTF-16 code units
// (including isolated surrogates); Numbers are IEEE-754 bits, preserving -0/NaN.
// Domain codecs must additionally validate their named constructors before use.
func validateWire(data []byte) error {
	var value any
	if err := json.Unmarshal(data, &value); err != nil {
		return fmt.Errorf("wire-json: %w", err)
	}
	var check func(any, int) bool
	check = func(v any, depth int) bool {
		if depth > 4096 {
			return false
		}
		a, ok := v.([]any)
		if !ok || len(a) == 0 {
			return false
		}
		tag, ok := a[0].(string)
		if !ok {
			return false
		}
		str := func(i int) string { s, _ := a[i].(string); return s }
		switch tag {
		case "unit":
			return len(a) == 1
		case "boolean":
			if len(a) != 2 {
				return false
			}
			_, ok := a[1].(bool)
			return ok
		case "int":
			if len(a) != 2 || !integerPattern.MatchString(str(1)) {
				return false
			}
			_, err := strconv.ParseInt(str(1), 10, 64)
			return err == nil
		case "number":
			return len(a) == 2 && floatPattern.MatchString(str(1))
		case "string":
			if len(a) != 2 {
				return false
			}
			s, ok := a[1].(string)
			return ok && hexUnitsPattern.MatchString(s)
		case "array", "ctor":
			i := 1
			if tag == "ctor" {
				if len(a) != 3 || !tagPattern.MatchString(str(1)) {
					return false
				}
				i = 2
			} else if len(a) != 2 {
				return false
			}
			items, ok := a[i].([]any)
			if !ok {
				return false
			}
			for _, item := range items {
				if !check(item, depth+1) {
					return false
				}
			}
			return true
		case "record":
			if len(a) != 2 {
				return false
			}
			items, ok := a[1].([]any)
			if !ok {
				return false
			}
			last := ""
			first := true
			for _, item := range items {
				pair, ok := item.([]any)
				if !ok || len(pair) != 2 {
					return false
				}
				key, ok := pair[0].(string)
				if !ok || !hexUnitsPattern.MatchString(key) || (!first && key <= last) || !check(pair[1], depth+1) {
					return false
				}
				first = false
				last = key
			}
			return true
		}
		return false
	}
	if !check(value, 0) {
		return fmt.Errorf("wire-shape")
	}
	return nil
}

func sortedSettings(settings []Setting) ([]string, error) {
	copy := append([]Setting{}, settings...)
	sort.Slice(copy, func(i, j int) bool { return copy[i].Name < copy[j].Name })
	parts := []string{}
	for i, setting := range copy {
		if setting.Name == "" || (i > 0 && setting.Name == copy[i-1].Name) {
			return nil, fmt.Errorf("duplicate/empty setting")
		}
		parts = append(parts, setting.Name, setting.Value)
	}
	return parts, nil
}

