#!/usr/bin/env python3
"""Check actual target-action allocations after all primary timings are complete."""
from pathlib import Path
import hashlib,json,os,re,runpy,subprocess
S=Path(__file__).resolve().parent;W=S.parents[1];P=W/'proofs/action-allocations';assert not P.exists()
r=json.loads((W/'campaign/results.json').read_text());P.mkdir()
C=runpy.run_path(str(S/'compare-generated.py'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
env=dict(os.environ,GOWORK='off',GOGC='800')
for key in ['GOMAXPROCS','GOFLAGS','GOEXPERIMENT']:env.pop(key,None)
allcases=['Prime Sieve','Tail Call Optimization','effect/ref-write-10000','string/cp-take-unicode-1500'];results={}
for side in ['before','after']:
 results[side]={}
 for suite,selected in [('core',allcases[:2]),('all',allcases[2:])]:
  build=W/(side+'-'+suite);inventory=C['inventory'](build);owners={}
  cases=[(name,r['all_campaign']['all_tests'][name]) for name in selected]
  for name,row in cases:
   getter='Get_'+row['module'].replace('.','_')+('_act' if suite=='core' else '_prepare')
   paths=[str(Path(key).parent) for key,value in inventory['sections'].items() if ('func '+getter+'(').encode() in value]
   assert len(paths)==1,(name,paths);owners[name]=(paths[0],getter)
  packages=sorted(set(x[0] for x in owners.values()));aliases={n:'p'+str(i) for i,n in enumerate(packages)}
  imports=';'.join(aliases[n]+' "gopurs/output/'+n+'"' for n in packages)
  entries=[]
  for name,row in cases:
   action=aliases[owners[name][0]]+'.'+owners[name][1]+'()'
   if suite=='all':action='r.Apply('+action+',r.Value{})'
   entries.append('{'+json.dumps(name)+','+action+','+str(row['expected'])+'}')
  source='''package main
import("encoding/json";"os";"testing";r "gopurs/output/gopurs_runtime";'''+imports+''')
func adapt(action r.Value) func() int {
 if native,ok:=r.FunctionData[func() int64](action);ok{return func() int{return int(native())}}
 return func() int{return r.Unbox[int](r.Apply(action,r.Value{}))}
}
func main(){
 cases:=[]struct{name string;action r.Value;expected int64}{'''+','.join(entries)+'''}
 values:=map[string]float64{}
 for _,c:=range cases{
  runOriginal:=adapt(c.action)
  run:=func(){if int64(runOriginal())!=c.expected{panic("unexpected original-action result")}}
  run();values[c.name]=testing.AllocsPerRun(1000,run)
 }
 if err:=json.NewEncoder(os.Stdout).Encode(values);err!=nil{panic(err)}
}
'''
  stem=side+'-'+suite;main=P/(stem+'.go');main.write_text(source);binary=P/(stem+'-probe')
  command=['go','build','-pgo=off','-o',str(binary),str(main)]
  process=subprocess.run(command,cwd=build/'output',env=env,text=True,capture_output=True)
  (P/(stem+'-build.stdout')).write_text(process.stdout);(P/(stem+'-build.stderr')).write_text(process.stderr);process.check_returncode()
  output=subprocess.run([str(binary)],cwd=build/'output',env=env,text=True,capture_output=True);output.check_returncode();assert not output.stderr
  (P/(stem+'.stdout')).write_text(output.stdout);values=json.loads(output.stdout)
  assert set(values)==set(owners) and all(value>=0 for value in values.values())
  assert C['inventory'](build)['provenance']==inventory['provenance']
  results[side][suite]={'allocations_per_action':values,'expected_result_checks_per_case':1002,'allocs_per_run_iterations':1000,'command':command,'binary_sha256':sha(binary),'source_sha256':sha(main),'original_build':inventory['provenance'],'stdout':output.stdout}
manifest={'validated':True,'timings_measured':False,'method':'testing.AllocsPerRun(1000) on actual saved target actions, including their opaque calls, via the official FunctionData/Unbox-Apply callback adaptation. Each run verifies the expected result. One warm-up plus one initial result check means 1002 checks per case/build. AllocsPerRun temporarily sets GOMAXPROCS=1. Four distinct fixed expected cases; this is not varied-input validation.','GOGC':'800','results':results}
(P/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({side:{k:v for suite in rows.values() for k,v in suite['allocations_per_action'].items()} for side,rows in results.items()},indent=2))

