 ratios=[t[n]/c[n] for n in t]
 expected[side]={'total':sum(t.values())/sum(c.values()),'arithmetic':statistics.fmean(ratios),'median':statistics.median(ratios),'geometric':math.exp(statistics.fmean(math.log(x) for x in ratios))}
 for key,value in expected[side].items():assert math.isclose(value,r['aggregates'][side][key],rel_tol=1e-12)
 assert math.isclose(sum(t.values())/1000,r['matched37_total_ms'][side],rel_tol=1e-12)
assert math.isclose(sum(c.values())/1000,8.777346938669927,rel_tol=1e-12)
x={'status':'passed','cases':37,'method':'Independent computation from frozen C37 and medians of three retained process minima per case; tolerance 1e-12 relative.','aggregates':expected,'c_total_ms':sum(c.values())/1000,'campaign_sha256':hashlib.sha256((W/'campaign/results.json').read_bytes()).hexdigest()}
