import fs from 'node:fs';
const rows=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const text=units=>{let s='';for(const unit of units)s+=String.fromCharCode(unit);return s;};
const checksum=s=>{let total=0;for(const cp of s)total=(total+cp.codePointAt(0))|0;return total;};
for(const row of rows){if(row.domain!=='js-utf16')continue;let value;
 if(row.kind==='concat')value=checksum(row.fragment_units.map(text).join(''));
 else {const s=text(row.units);if(row.kind==='checksum')value=checksum(s);if(row.kind==='take')value=checksum(Array.from(s).slice(0,Math.max(0,row.count)).join(''));if(row.kind==='split'){const parts=s.split(text(row.separator_units));value=parts.reduce((total,part)=>(total+checksum(part))|0,parts.length);}}
 console.log(`${row.id} ${value}`);
}

