from pathlib import Path
import json,hashlib,subprocess,sys
wave=Path(__file__).resolve().parents[1];side=sys.argv[1];assert side in ['before','after']
source=wave/(side+'-core/output');out=wave/'proofs'/('loop-inputs-'+side);out.mkdir(exist_ok=True)
functions={'prime':'Call_Test_Primes___gopurs_list_progression_fold_0','tco':'Call_Test_TCO_deepTailRec','prime_action':'Get_Test_Primes_act','tco_action':'Get_Test_TCO_act'}
paths={}
for p in (source/'purescript').rglob('*.go'):
 text=p.read_text()
 for key,name in functions.items():
  if 'func '+name+'(' in text:paths[key]=p
assert set(paths)==set(functions),paths
imports={key:'gopurs/output/purescript/'+p.parent.name for key,p in paths.items()}
code='package main\nimport("encoding/json";"os";"fmt";r "gopurs/output/gopurs_runtime"; _ "gopurs/output/purescript/init_all";'+''.join(key+' "'+value+'";' for key,value in imports.items())+')\n'
code+=r"""
type Input struct { Kind string; Lower,Upper,Count,Seed,Expected int64 }
func main(){var cases []Input;if err:=json.NewDecoder(os.Stdin).Decode(&cases);err!=nil{panic(err)};primeCount,tcoCount:=0,0
 for _,c:=range cases { var got int64
  if c.Kind=="prime" {got=prime.Call_Test_Primes___gopurs_list_progression_fold_0(c.Lower,c.Upper,c.Seed);primeCount++} else {got=tco.Call_Test_TCO_deepTailRec(c.Count,c.Seed);boxed:=r.Apply2(tco.Get_Test_TCO_deepTailRec(),r.Int(c.Count),r.Int(c.Seed)).IntVal;if boxed!=c.Expected{panic(fmt.Sprintf("boxed %+v got%d",c,boxed))};tcoCount++}
  if got!=c.Expected{panic(fmt.Sprintf("%+v got%d",c,got))}
 }
 if got:=r.Apply(prime_action.Get_Test_Primes_act(),r.Value{}).IntVal;got!=21536{panic(fmt.Sprintf("prime action %d",got))}
 if got:=r.Apply(tco_action.Get_Test_TCO_act(),r.Value{}).IntVal;got!=100000{panic(fmt.Sprintf("TCO action %d",got))}
 fmt.Printf("%d prime native cases, %d TCO native+boxed cases, two actual default actions passed\n",primeCount,tcoCount)
}
"""
(out/'main.go').write_text(code);(out/'go.mod').write_text('module looporacle\n\ngo 1.27\n\nrequire gopurs/output v0.0.0\nreplace gopurs/output => '+str(source)+'\n')
wrap=lambda n:((n+(1<<31))%(1<<32))-(1<<31)
cases=[]
for lower,upper in [(2,u) for u in [2,3,4,9,24,25,26,48,49,50,500,1022,1023,1024,1025,2048,10000]]+[(l,l+width) for l in [3,4,6,10,1000,2147482000] for width in [0,1,2,31,511,1023]]:
 heads=[]
 for v in range(lower,upper+1):
  if all(v%h!=0 for h in heads):heads.append(v)
 for seed in [-2147483648,-17,0,23,2147483647]:cases.append({'Kind':'prime','Lower':lower,'Upper':upper,'Seed':seed,'Expected':wrap(seed+sum(heads))})
for count in [0,1,2,3,7,31,1000,10000,100000,4294967297,-4294967295]:
 for seed in [-2147483648,-1,0,2147483647,2147483648,4294967297,9223372036854775807,-9223372036854775808]:
  n=count;value=seed;steps=0
  while n!=0:
   value=wrap(value+n%3);n=wrap(n-1);steps+=1;assert steps<=100000
  cases.append({'Kind':'tco','Count':count,'Seed':seed,'Expected':value})
(out/'inputs.json').write_text(json.dumps(cases,indent=2)+'\n')
frozen=list(set(paths.values()))+[source/'gopurs_runtime/runtime.go',wave/(side+'-core/benchmark')]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
before={str(p):sha(p) for p in frozen}
build=subprocess.run(['go','build','-mod=mod','-o','oracle','.'],cwd=out,text=True,capture_output=True);(out/'build.log').write_text(build.stdout+build.stderr);assert build.returncode==0,(build.stdout+build.stderr)
run=subprocess.run([str(out/'oracle')],input=(out/'inputs.json').read_text(),cwd=out,text=True,capture_output=True);(out/'stdout.txt').write_text(run.stdout);(out/'stderr.txt').write_text(run.stderr);assert run.returncode==0,(run.stdout,run.stderr)
assert before=={str(p):sha(p) for p in frozen}
manifest={'status':'passed','side':side,'prime_cases':265,'tco_cases':88,'tco_paths':['native','boxed Apply2'],'actual_default_actions':2,'inputs':'JSON stdin, so no compile-time input substitution','oracle':'prime ordered elimination on dynamic interval; TCO Python arbitrary-precision iterative modulo and Int32 wrapping; wide native values a separate domain from JS','frozen_files':before,'artifacts':{str(p.relative_to(out)):sha(p) for p in out.iterdir() if p.is_file() and p.name!='manifest.json'}}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(run.stdout,end='')

